    # ========== CHUD QUEUE PROCESSOR ==========
    async def process_chud_queue(chat_id, sender_id):
        target = (chat_id, sender_id)
        if target in processing_targets:
            return
        processing_targets.add(target)
        while reply_queues[target]:
            event = reply_queues[target].popleft()
            try:
                if fast_mode:
                    await asyncio.sleep(random.randint(1, int(fast_delay * 2)))
                else:
                    await asyncio.sleep(random.randint(1, 3))
                msgs = chud_custom_messages.get(target) or default_chud_messages
                idx = reply_index[target]
                line = msgs[idx]
                reply_index[target] = (idx + 1) % max(1, len(msgs))
                
                final_text = line
                if global_prefix_list:
                    prefix = random.choice(global_prefix_list)
                    final_text = f"{prefix} {final_text}"
                if global_username_list:
                    username = random.choice(global_username_list)
                    final_text = f"{final_text} {username}"
                if global_tag_list:
                    tag_text = " ".join(global_tag_list)
                    final_text = f"{final_text} {tag_text}"
                if global_suffix_list:
                    suffix = random.choice(global_suffix_list)
                    final_text = f"{final_text} {suffix}"
                
                await event.reply(final_text)
            except Exception as e:
                print(f"Chud reply failed: {e}")
        processing_targets.discard(target)
    
    # ========== ONEWORD COMMANDS ==========
    
    @client.on(events.NewMessage(pattern=r"^\.oneword(?:\s+(.+))?$"))
    async def oneword_command(event):
        if not is_allowed(event.sender_id):
            return
        user_id_str = str(event.sender_id)
        arg = event.pattern_match.group(1)
        words = None
        target_link = None
        target_user_id = None
        chat_id = None
        msg_id = None

        # If reply to a message
        if event.reply_to_msg_id:
            replied = await event.get_reply_message()
            if replied:
                chat_id = event.chat_id
                msg_id = replied.id
                target_link = f"t.me/c/{chat_id}/{msg_id}"
                if arg and "t.me/" not in arg:
                    words = arg.strip().split()
                elif arg and "t.me/" in arg:
                    parts = arg.split()
                    if len(parts) > 1:
                        words = parts[1:]
        else:
            if arg:
                parts = arg.split()
                first = parts[0]
                if "t.me/" in first:
                    target_link = first
                    if len(parts) > 1:
                        words = parts[1:]
                else:
                    target_user_id = await get_user_id_from_input(event, first)
                    if target_user_id:
                        try:
                            async for msg in client.iter_messages(event.chat_id, from_user=target_user_id, limit=1):
                                if msg:
                                    chat_id = event.chat_id
                                    msg_id = msg.id
                                    target_link = f"t.me/c/{chat_id}/{msg_id}"
                                    break
                        except:
                            pass
                        if not target_link:
                            await event.reply("❌ No recent message from that user.")
                            return
                        if len(parts) > 1:
                            words = parts[1:]
                    else:
                        await event.reply("❌ Usage: `.oneword (reply)` | `.oneword <link> [words]` | `.oneword @username [words]`")
                        return

        if not target_link:
            await event.reply("❌ Provide a target (reply, link, or username).")
            return

        if not chat_id or not msg_id:
            try:
                if "t.me/" in target_link:
                    parts = target_link.split("/")
                    if len(parts) >= 4 and parts[-3] == "c":
                        chat_id = int(parts[-2].split("?")[0])
                        msg_id = int(parts[-1].split("?")[0])
                    elif len(parts) >= 3:
                        chat_str = parts[-2]
                        msg_id = int(parts[-1].split("?")[0])
                        entity = await client.get_entity(chat_str)
                        chat_id = entity.id
                    else:
                        raise ValueError("Invalid link")
                else:
                    raise ValueError("Invalid link")
            except Exception as e:
                await event.reply(f"❌ Failed to parse link: {str(e)}")
                return

        try:
            target_msg = await client.get_messages(chat_id, ids=msg_id)
            if not target_msg:
                raise ValueError("Message not found")
        except Exception as e:
            await event.reply(f"❌ Error: {str(e)}")
            return

        # Set words - priority: custom > user default > global > default list
        if words:
            oneword_words[user_id_str] = words
        else:
            if user_id_str in user_oneword_default and user_oneword_default[user_id_str]:
                oneword_words[user_id_str] = user_oneword_default[user_id_str]
            elif GLOBAL_ONEWORD_LIST:
                oneword_words[user_id_str] = GLOBAL_ONEWORD_LIST
            else:
                oneword_words[user_id_str] = ONEWORD_LIST

        if not oneword_words.get(user_id_str, []):
            await event.reply("❌ No words available. Set default with `.setoneword`, use global, or provide words.")
            return

        # Stop existing oneword
        if oneword_active.get(user_id_str, False):
            oneword_active[user_id_str] = False
            if oneword_task.get(user_id_str) and not oneword_task[user_id_str].done():
                oneword_task[user_id_str].cancel()

        # Start new oneword
        oneword_active[user_id_str] = True
        oneword_chat_id[user_id_str] = chat_id
        oneword_target_msg_id[user_id_str] = msg_id
        oneword_index[user_id_str] = 0

        await event.reply(
            f"✅ **ONEWORD STARTED**\n\n"
            f"Target: `{target_link}`\n"
            f"Words: `{' '.join(oneword_words[user_id_str])}`\n"
            f"Delay: `{global_delay}s`\n\n"
            "Use `.stoponeword` to stop."
        )
        
        oneword_task[user_id_str] = asyncio.create_task(oneword_loop(user_id_str))

    @client.on(events.NewMessage(pattern=r"^\.stoponeword$"))
    async def stoponeword_command(event):
        if not is_allowed(event.sender_id):
            return
        user_id_str = str(event.sender_id)
        if not oneword_active.get(user_id_str, False):
            await event.reply("ℹ️ No active oneword to stop.")
            return
        oneword_active[user_id_str] = False
        if oneword_task.get(user_id_str) and not oneword_task[user_id_str].done():
            oneword_task[user_id_str].cancel()
        await event.reply("🛑 **ONEWORD STOPPED**")

    @client.on(events.NewMessage(pattern=r"^\.setoneword(?:\s+(.+))?$"))
    async def setoneword_command(event):
        if not is_allowed(event.sender_id):
            return
        user_id_str = str(event.sender_id)
        arg = event.pattern_match.group(1)
        words = None
        
        if arg:
            words = arg.strip().split()
        elif event.reply_to_msg_id:
            replied = await event.get_reply_message()
            if not replied:
                await event.reply("❌ No replied message found.")
                return
            content = None
            if replied.text:
                content = replied.text
            elif replied.document:
                mime = replied.document.mime_type
                is_text = False
                if mime and mime.startswith("text/"):
                    is_text = True
                elif replied.document.attributes:
                    for attr in replied.document.attributes:
                        if hasattr(attr, 'file_name') and attr.file_name and attr.file_name.lower().endswith('.txt'):
                            is_text = True
                            break
                if not is_text:
                    await event.reply("❌ Replied file is not a text file.")
                    return
                try:
                    import tempfile
                    with tempfile.NamedTemporaryFile(delete=False, suffix=".txt") as tmp:
                        tmp_path = tmp.name
                    await client.download_media(replied, file=tmp_path)
                    with open(tmp_path, "r", encoding="utf-8") as f:
                        content = f.read()
                    os.unlink(tmp_path)
                except Exception as e:
                    await event.reply(f"❌ Failed to read file: {str(e)}")
                    return
            else:
                await event.reply("❌ No text or file found in replied message.")
                return
            if content:
                words = content.strip().split()
            else:
                await event.reply("❌ No content found.")
                return
        else:
            await event.reply("❌ Usage: `.setoneword word1 word2 ...` or reply to text/file.")
            return
        
        if not words:
            await event.reply("❌ No words found!")
            return
        
        user_oneword_default[user_id_str] = words
        save_data()
        await event.reply(f"✅ **DEFAULT WORDS SET**\n\nWords: `{' '.join(words)}`")

    @client.on(events.NewMessage(pattern=r"^\.addoneword\s+(.+)$"))
    async def addoneword_command(event):
        if not is_allowed(event.sender_id):
            return
        user_id_str = str(event.sender_id)
        word = event.pattern_match.group(1).strip()
        if not word:
            await event.reply("❌ Please provide a word.")
            return
        
        user_list = user_oneword_default.get(user_id_str, [])
        user_list.append(word)
        user_oneword_default[user_id_str] = user_list
        save_data()
        await event.reply(f"✅ **WORD ADDED**\n\nAdded: `{word}`\nNew list: `{' '.join(user_list)}`")

    @client.on(events.NewMessage(pattern=r"^\.removeoneword\s+(\d+)$"))
    async def removeoneword_command(event):
        if not is_allowed(event.sender_id):
            return
        user_id_str = str(event.sender_id)
        try:
            index = int(event.pattern_match.group(1))
        except:
            await event.reply("❌ Invalid index. Use number like: `.removeoneword 1`")
            return
        
        user_list = user_oneword_default.get(user_id_str, [])
        if index < 1 or index > len(user_list):
            await event.reply(f"❌ Invalid index (1-{len(user_list)})")
            return
        
        removed = user_list.pop(index - 1)
        user_oneword_default[user_id_str] = user_list
        save_data()
        await event.reply(f"✅ **WORD REMOVED**\n\nRemoved: `{removed}`\nNew list: `{' '.join(user_list)}`")

    @client.on(events.NewMessage(pattern=r"^\.listoneword$"))
    async def listoneword_command(event):
        if not is_allowed(event.sender_id):
            return
        user_id_str = str(event.sender_id)
        user_list = user_oneword_default.get(user_id_str, [])
        
        if not user_list:
            await event.reply("📭 **NO WORDS SET**\n\nUse `.setoneword word1 word2 ...` to set default words.")
            return
        
        msg = "📋 **YOUR ONEWORD LIST**\n\n"
        for i, word in enumerate(user_list, 1):
            msg += f"{i}. `{word}`\n"
        await event.reply(msg)

    @client.on(events.NewMessage(pattern=r"^\.gsetoneword(?:\s+(.+))?$"))
    async def gsetoneword_command(event):
        if event.sender_id != OWNER_ID:
            await event.reply("❌ This command is only for the bot owner.")
            return
        arg = event.pattern_match.group(1)
        words = None
        
        if arg:
            words = arg.strip().split()
        elif event.reply_to_msg_id:
            replied = await event.get_reply_message()
            if not replied:
                await event.reply("❌ No replied message found.")
                return
            content = None
            if replied.text:
                content = replied.text
            elif replied.document:
                mime = replied.document.mime_type
                is_text = False
                if mime and mime.startswith("text/"):
                    is_text = True
                elif replied.document.attributes:
                    for attr in replied.document.attributes:
                        if hasattr(attr, 'file_name') and attr.file_name and attr.file_name.lower().endswith('.txt'):
                            is_text = True
                            break
                if not is_text:
                    await event.reply("❌ Replied file is not a text file.")
                    return
                try:
                    import tempfile
                    with tempfile.NamedTemporaryFile(delete=False, suffix=".txt") as tmp:
                        tmp_path = tmp.name
                    await client.download_media(replied, file=tmp_path)
                    with open(tmp_path, "r", encoding="utf-8") as f:
                        content = f.read()
                    os.unlink(tmp_path)
                except Exception as e:
                    await event.reply(f"❌ Failed to read file: {str(e)}")
                    return
            else:
                await event.reply("❌ No text or file found in replied message.")
                return
            if content:
                words = content.strip().split()
            else:
                await event.reply("❌ No content found.")
                return
        else:
            await event.reply("❌ Usage: `.gsetoneword word1 word2 ...` or reply to text/file.")
            return
        
        if not words:
            await event.reply("❌ No words found!")
            return
        
        GLOBAL_ONEWORD_LIST = words
        save_data()
        await event.reply(f"✅ **GLOBAL ONEWORD SET**\n\nWords: `{' '.join(GLOBAL_ONEWORD_LIST)}`")

