    # ========== .UR COMMAND ==========
    @client.on(events.NewMessage(pattern=r"\.ur(?:\s+(.+))?"))
    async def ur_command(event):
        global global_tag_list
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        
        arg = event.pattern_match.group(1) if event.pattern_match.group(1) else None
        if not arg:
            global_tag_list = []
            save_data()
            reply_msg = await event.reply("✅ **TAGS CLEARED**")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
                asyncio.create_task(auto_delete(event.message))
            return
        
        user_ids = []
        for part in arg.split(','):
            uid = part.strip()
            if uid.isdigit():
                user_ids.append(int(uid))
            else:
                try:
                    user = await client.get_entity(uid)
                    user_ids.append(user.id)
                except:
                    pass
        
        if not user_ids:
            reply_msg = await event.reply("❌ Invalid user ID(s)")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
            return
        
        global_tag_list = []
        for uid in user_ids:
            try:
                user = await client.get_entity(uid)
                mention = f"[{user.first_name or user.username or str(uid)}](tg://user?id={uid})"
                global_tag_list.append(mention)
            except:
                global_tag_list.append(f"`{uid}`")
        
        save_data()
        reply_msg = await event.reply(f"✅ **TAGS SET:** {len(global_tag_list)} users\n\n{', '.join(global_tag_list)}")
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg))
            asyncio.create_task(auto_delete(event.message))
    
