    # ========== .FAST COMMAND ==========
    @client.on(events.NewMessage(pattern=r"\.fast(?:\s+(.+))?"))
    async def fast_command(event):
        global fast_mode, fast_delay
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        
        arg = event.pattern_match.group(1) if event.pattern_match.group(1) else None
        
        if not arg:
            status = "ON ⚡" if fast_mode else "OFF 🐢"
            reply_msg = await event.reply(f"✅ **FAST MODE: {status}**\n\nDelay: {fast_delay if fast_mode else global_delay}s")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg, delay=10))
                asyncio.create_task(auto_delete(event.message))
            return
        
        if arg.lower() == "off":
            fast_mode = False
            save_data()
            reply_msg = await event.reply(f"✅ **FAST MODE: OFF 🐢**\n\nUsing normal delay: {global_delay}s")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
                asyncio.create_task(auto_delete(event.message))
            return
        
        if arg.lower() == "on":
            fast_mode = True
            if fast_delay == 0:
                fast_delay = 0.5
            save_data()
            reply_msg = await event.reply(f"✅ **FAST MODE: ON ⚡**\n\nDelay: {fast_delay}s")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
                asyncio.create_task(auto_delete(event.message))
            return
        
        reply_msg = await event.reply(f"❌ Use: `.fast on`, `.fast off`, or `.fast`")
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg))
    
    @client.on(events.NewMessage(pattern=r"\.fastmode(?:\s+(.+))?"))
    async def fastmode_command(event):
        global fast_mode, fast_delay
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        
        arg = event.pattern_match.group(1) if event.pattern_match.group(1) else None
        
        if not arg:
            status = "ON ⚡" if fast_mode else "OFF 🐢"
            reply_msg = await event.reply(f"✅ **FAST MODE: {status}**\n\nDelay: {fast_delay if fast_mode else global_delay}s")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg, delay=10))
                asyncio.create_task(auto_delete(event.message))
            return
        
        try:
            delay = float(arg)
            if delay < 0.1:
                reply_msg = await event.reply(f"❌ Minimum delay: 0.1s")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg))
                return
            if delay > 10:
                reply_msg = await event.reply(f"❌ Maximum delay: 10s")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg))
                return
            
            fast_delay = delay
            fast_mode = True
            save_data()
            reply_msg = await event.reply(f"✅ **FAST MODE: ON ⚡**\n\nDelay: {fast_delay}s")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
                asyncio.create_task(auto_delete(event.message))
        except ValueError:
            reply_msg = await event.reply(f"❌ Use: `.fastmode 0.5`")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
    
