    # ========== .CLONE COMMAND ==========
    @client.on(events.NewMessage(pattern=r"\.clone$"))
    async def clone_command(event):
        global clone_mode, clone_target, original_name, original_bio, original_photo
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        
        if event.is_reply:
            replied = await event.get_reply_message()
            target_id = replied.sender_id
            user = await client.get_entity(target_id)
            
            me = await client.get_me()
            original_name = me.first_name or ""
            if me.last_name:
                original_name += f" {me.last_name}"
            if hasattr(me, 'about') and me.about:
                original_bio = me.about
            if me.photo:
                original_photo = await client.download_profile_photo(me)
            
            if user.first_name:
                await client(functions.account.UpdateProfileRequest(first_name=user.first_name))
            if user.last_name:
                await client(functions.account.UpdateProfileRequest(last_name=user.last_name))
            
            if hasattr(user, 'about') and user.about:
                await client(functions.account.UpdateProfileRequest(about=user.about))
            
            if user.photo:
                photo_path = await client.download_profile_photo(user)
                if photo_path:
                    await client(functions.photos.UploadProfilePhotoRequest(
                        file=await client.upload_file(photo_path)
                    ))
                    os.remove(photo_path)
            
            clone_mode = True
            clone_target = target_id
            save_data()
            
            reply_msg = await event.reply(f"🧬 **CLONE MODE: ON**\n\n✅ Cloned: {user.first_name or 'User'}")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
                asyncio.create_task(auto_delete(event.message))
            return
        
        status = "ON 🧬" if clone_mode else "OFF 🔒"
        if clone_mode and clone_target:
            try:
                user = await client.get_entity(clone_target)
                status = f"ON 🧬 (Cloned: {user.first_name or 'User'})"
            except:
                pass
        
        reply_msg = await event.reply(f"🧬 **CLONE MODE: {status}**")
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg, delay=10))
            asyncio.create_task(auto_delete(event.message))
    
    # ========== .RECOVER COMMAND ==========
    @client.on(events.NewMessage(pattern=r"\.recover$"))
    async def recover_command(event):
        global clone_mode, clone_target, original_name, original_bio, original_photo
        global global_prefix_list, global_username_list, global_tag_list
        global global_suffix_list, global_block_list, repeat_count
        global fast_mode, fast_delay, global_mode
        global active_users, active_users2, active_users3, active_users4
        global active_users5, active_users6, active_users7
        global active_font1_users, active_font2_users, active_font3_users
        global active_font4_users, active_font5_users, active_font6_users, active_font7_users
        global custom_messages, custom_messages2, custom_messages3, custom_messages4
