    # ========== .CHUD COMMANDS ==========
    @client.on(events.NewMessage(pattern=r"\.chud(?:\s+(.+))?"))
    async def chud_command(event):
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        chat_id = event.chat_id
        target_id = None
        texts_str = None
        
        if event.is_reply:
            try:
                replied = await event.get_reply_message()
                target_id = replied.sender_id
                texts_str = event.pattern_match.group(1) if event.pattern_match.group(1) else None
            except:
                reply_msg = await event.reply("❌ Could not get replied user.")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg))
                return
        else:
            arg = event.pattern_match.group(1) if event.pattern_match.group(1) else None
            if not arg:
                reply_msg = await event.reply("❌ Usage: `.chud <reply/id/username> [text1,text2,...]`")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg))
                return
            if ',' in arg:
                parts = arg.split(',')
                first = parts[0].strip()
                texts_str = ','.join(parts[1:]).strip()
                try:
                    if first.isdigit():
                        target_id = int(first)
                    else:
                        user = await client.get_entity(first)
                        target_id = user.id
                except:
                    reply_msg = await event.reply(f"❌ Invalid target: {first}")
                    if is_saved:
                        asyncio.create_task(auto_delete(reply_msg))
                    return
            else:
                try:
                    if arg.isdigit():
                        target_id = int(arg)
                    else:
                        user = await client.get_entity(arg)
                        target_id = user.id
                except:
                    reply_msg = await event.reply(f"❌ Invalid target: {arg}")
                    if is_saved:
                        asyncio.create_task(auto_delete(reply_msg))
                    return
        
        if not target_id:
            reply_msg = await event.reply("❌ Target user not found.")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
            return
        
        target = (chat_id, target_id)
        if texts_str:
            msgs = [t.strip() for t in texts_str.split(",") if t.strip()]
            if msgs:
                chud_custom_messages[target] = msgs
        
        active_autoreply.add(target)
        save_data()
        used_msgs = chud_custom_messages.get(target, default_chud_messages)
        try:
            await client.send_message("me", f"✅ CHUD enabled for `{target_id}`!\nMessages set: {len(used_msgs)}")
        except:
            pass
        try:
            await event.delete()
        except:
            pass
    
