    @client.on(events.NewMessage(pattern=r"\.mental(?:\s+(.+))?"))
    async def mental_command(event):
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        target_id = None
        custom_texts = None
        
        if event.is_reply:
            replied = await event.get_reply_message()
            target_id = replied.sender_id
        elif event.pattern_match.group(1):
            arg = event.pattern_match.group(1).strip()
            if ',' in arg:
                first_comma = arg.find(',')
                id_part = arg[:first_comma].strip()
                msg_part = arg[first_comma+1:].strip()
                target_id = await get_user_id_from_input(event, id_part)
                if target_id:
                    custom_texts = [m.strip() for m in msg_part.split(',') if m.strip()]
            else:
                target_id = await get_user_id_from_input(event, arg)
        
        if not target_id:
            reply_msg = await event.reply("❌ Use: .mental @user or reply")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
            return
        
        # Disable other mental systems
        active_users2.discard(target_id)
        active_users3.discard(target_id)
        active_users4.discard(target_id)
        active_users5.discard(target_id)
        active_users6.discard(target_id)
        active_users7.discard(target_id)
        active_font1_users.discard(target_id)
        active_font2_users.discard(target_id)
