        active_font5_users.discard(target_id)
        active_font6_users.discard(target_id)
        active_font7_users.discard(target_id)
        
        custom_messages2.pop(target_id, None)
        custom_messages3.pop(target_id, None)
        custom_messages4.pop(target_id, None)
        custom_messages5.pop(target_id, None)
        custom_messages6.pop(target_id, None)
        custom_messages7.pop(target_id, None)
        custom_font1_messages.pop(target_id, None)
        custom_font2_messages.pop(target_id, None)
        custom_font3_messages.pop(target_id, None)
        custom_font4_messages.pop(target_id, None)
        custom_font5_messages.pop(target_id, None)
        custom_font6_messages.pop(target_id, None)
        custom_font7_messages.pop(target_id, None)
        
        active_users.add(target_id)
        custom_messages[target_id] = custom_texts if custom_texts else default_messages
        save_data()
        
        target_display = await get_user_display(target_id)
