    @client.on(events.NewMessage(pattern=r"\.stopar$"))
    async def stopar_command(event):
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        if not event.is_reply:
            reply_msg = await event.reply("❌ Reply to a user's message")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
            return
        replied = await event.get_reply_message()
        target_id = replied.sender_id
        chat_id = event.chat_id
        if (chat_id, target_id) in auto_react_users:
            del auto_react_users[(chat_id, target_id)]
            save_data()
            target_display = await get_user_display(target_id)
            reply_msg = await event.reply(f"✅ **AUTO-REACT REMOVED**\n\nUser: {target_display}")
        else:
            target_display = await get_user_display(target_id)
            reply_msg = await event.reply(f"❌ No auto-react set for {target_display}")
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg))
            asyncio.create_task(auto_delete(event.message))
    
