    # ========== LIST ACTIVE ==========
    @client.on(events.NewMessage(pattern=r"\.listactive$"))
    async def listactive_command(event):
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        
        total = len(active_users) + len(active_users2) + len(active_users3) + len(active_users4)
        total += len(active_users5) + len(active_users6) + len(active_users7)
        total += len(active_font1_users) + len(active_font2_users) + len(active_font3_users)
        total += len(active_font4_users) + len(active_font5_users) + len(active_font6_users) + len(active_font7_users)
        total += len(active_autoreply)
        
        if total == 0:
            reply_msg = await event.reply("📭 No active users")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
            return
        
        msg = "**📋 ACTIVE USERS:**\n\n"
        
        systems = [
            (active_users, custom_messages, ".mental"),
            (active_users2, custom_messages2, ".mental2"),
            (active_users3, custom_messages3, ".mental3"),
            (active_users4, custom_messages4, ".mental4"),
            (active_users5, custom_messages5, ".mental5"),
            (active_users6, custom_messages6, ".mental6"),
            (active_users7, custom_messages7, ".mental7"),
            (active_font1_users, custom_font1_messages, ".font1"),
            (active_font2_users, custom_font2_messages, ".font2"),
            (active_font3_users, custom_font3_messages, ".font3"),
            (active_font4_users, custom_font4_messages, ".font4"),
            (active_font5_users, custom_font5_messages, ".font5"),
            (active_font6_users, custom_font6_messages, ".font6"),
            (active_font7_users, custom_font7_messages, ".font7"),
        ]
        
        for users_set, msgs_dict, name in systems:
            if users_set:
                msg += f"**{name}:**\n"
                for uid in users_set:
                    msg_count = len(msgs_dict.get(uid, []))
                    user_display = await get_user_display(uid)
                    msg += f"  • {user_display} | Msgs: {msg_count}\n"
                msg += "\n"
        
        if active_autoreply:
            msg += f"**.chud:**\n"
            for (c, u) in active_autoreply:
                msg_count = len(chud_custom_messages.get((c, u), []))
                user_display = await get_user_display(u)
                msg += f"  • {user_display} | Msgs: {msg_count}\n"
        
        reply_msg = await event.reply(msg)
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg, delay=15))
            asyncio.create_task(auto_delete(event.message))
    
    # ========== SHOW ==========
