    @client.on(events.NewMessage(pattern=r"\.bm$"))
    async def bm_command(event):
        if is_allowed(event.sender_id):
            is_saved = event.is_private and event.chat_id == OWNER_ID
            reply_msg = await event.reply("**⚡ 𝐑ᴀɴᴅɪ𝐁ᴀᴀᴢ 𝐃ᴀᴅᴅʏ 𝐈s 𝐇ᴇʀᴇ**")
