    # ========== SUDO ==========
    @client.on(events.NewMessage(pattern=r"\.sudo(?:\s+(.+))?"))
    async def sudo_command(event):
        if event.sender_id != OWNER_ID:
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        target_id = None
        if event.is_reply:
            replied = await event.get_reply_message()
            target_id = replied.sender_id
        elif event.pattern_match.group(1):
            input_str = event.pattern_match.group(1).strip()
            target_id = await get_user_id_from_input(event, input_str)
        if not target_id:
            reply_msg = await event.reply("❌ Use: .sudo @user or reply")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
            return
        sudo_users.add(target_id)
        save_data()
        user_display = await get_user_display(target_id)
        reply_msg = await event.reply(f"✅ **SUDO ADDED**\n\n👤 {user_display}")
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg))
            asyncio.create_task(auto_delete(event.message))
    
    @client.on(events.NewMessage(pattern=r"\.rmsudo(?:\s+(.+))?"))
    async def rmsudo_command(event):
        if event.sender_id != OWNER_ID:
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        target_id = None
        if event.is_reply:
            replied = await event.get_reply_message()
            target_id = replied.sender_id
        elif event.pattern_match.group(1):
            input_str = event.pattern_match.group(1).strip()
            target_id = await get_user_id_from_input(event, input_str)
        if not target_id:
            reply_msg = await event.reply("❌ Use: .rmsudo @user or reply")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
            return
        if target_id in sudo_users:
            sudo_users.discard(target_id)
            save_data()
            user_display = await get_user_display(target_id)
            reply_msg = await event.reply(f"✅ **SUDO REMOVED**\n\n👤 {user_display}")
        else:
            user_display = await get_user_display(target_id)
            reply_msg = await event.reply(f"❌ {user_display} is not sudo")
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg))
            asyncio.create_task(auto_delete(event.message))
    
    @client.on(events.NewMessage(pattern=r"\.showsudo$"))
    async def showsudo_command(event):
        if event.sender_id != OWNER_ID:
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        if not sudo_users:
            reply_msg = await event.reply("📭 No sudo users")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg))
            return
        msg = "**👑 SUDO USERS:**\n\n"
        for uid in sudo_users:
            user_display = await get_user_display(uid)
            msg += f"• {user_display}\n"
        reply_msg = await event.reply(msg)
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg, delay=10))
            asyncio.create_task(auto_delete(event.message))
    
