    # ========== SPAM COMMANDS ==========
    @client.on(events.NewMessage(pattern=r"\.spam\s+(\d+)\s+(.+)"))
    async def spam_command(event):
        global spam_running
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        
        if spam_running:
            reply_msg = await event.reply("⚠️ Spam already running! Use `.offspam` to stop.")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg, delay=5))
                asyncio.create_task(auto_delete(event.message, delay=5))
            return
        
        try:
            count = int(event.pattern_match.group(1))
            if count < 1:
                reply_msg = await event.reply("❌ Minimum count: 1")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg, delay=5))
                return
            if count > 1000:
                reply_msg = await event.reply("❌ Maximum count: 1000")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg, delay=5))
                return
                
            text = event.pattern_match.group(2).strip()
            if not text:
                reply_msg = await event.reply("❌ Message cannot be empty!")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg, delay=5))
                return
            
            target_id = None
            target_msg = None
            actual_text = text
            
            parts = text.split(maxsplit=1)
            if parts:
                first_part = parts[0]
                if first_part.startswith('@') or first_part.isdigit():
                    try:
                        user = await client.get_entity(first_part)
                        target_id = user.id
                        actual_text = parts[1] if len(parts) > 1 else ""
                        if not actual_text:
                            reply_msg = await event.reply("❌ No message to spam after target!")
                            if is_saved:
                                asyncio.create_task(auto_delete(reply_msg, delay=5))
                            return
                    except:
                        pass
            
            if event.is_reply and not target_id:
                try:
                    target_msg = await event.get_reply_message()
                    if target_msg:
                        target_id = target_msg.sender_id
                except:
                    pass
            
            chat_id = event.chat_id
            
            if target_id:
                user_display = await get_user_display(target_id)
                reply_msg = await event.reply(f"📨 Spam: {count} messages to {user_display}")
            else:
                reply_msg = await event.reply(f"📨 Spam: {count} messages in this chat")
            
            await asyncio.sleep(0.5)
            
            spam_running = True
            sent = 0
            msg_to_send = actual_text if actual_text else text
            
            for i in range(count):
                if not spam_running:
                    break
                try:
                    if target_msg:
                        await target_msg.reply(msg_to_send)
                    elif target_id:
                        await client.send_message(target_id, msg_to_send)
                    else:
                        await client.send_message(chat_id, msg_to_send)
                    sent += 1
                    await asyncio.sleep(0.15)
                except Exception as e:
                    print(f"Spam error: {e}")
                    break
            
            spam_running = False
            
            if target_id:
                await event.reply(f"✅ Spam done: {sent}/{count} messages sent to {user_display}")
            else:
                await event.reply(f"✅ Spam done: {sent}/{count} messages sent in this chat")
                
            if is_saved:
                asyncio.create_task(auto_delete(event.message, delay=5))
                
        except ValueError:
            reply_msg = await event.reply(f"❌ Use: `.spam 10 hello` or `.spam 5 @user hello`")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg, delay=5))
        except Exception as e:
            spam_running = False
            reply_msg = await event.reply(f"❌ Error: {e}")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg, delay=5))

    @client.on(events.NewMessage(pattern=r"\.delayspam\s+([\d\.]+)\s+(\d+)\s+(.+)"))
    async def delayspam_command(event):
        global spam_running
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        
        if spam_running:
            reply_msg = await event.reply("⚠️ Spam already running! Use `.offspam` to stop.")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg, delay=5))
                asyncio.create_task(auto_delete(event.message, delay=5))
            return
        
        try:
            delay = float(event.pattern_match.group(1))
            if delay < 0.1:
                reply_msg = await event.reply("❌ Minimum delay: 0.1 seconds")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg, delay=5))
                return
            if delay > 60:
                reply_msg = await event.reply("❌ Maximum delay: 60 seconds")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg, delay=5))
                return
                
            count = int(event.pattern_match.group(2))
            if count < 1:
                reply_msg = await event.reply("❌ Minimum count: 1")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg, delay=5))
                return
            if count > 500:
                reply_msg = await event.reply("❌ Maximum count: 500")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg, delay=5))
                return
                
            text = event.pattern_match.group(3).strip()
            if not text:
                reply_msg = await event.reply("❌ Message cannot be empty!")
                if is_saved:
                    asyncio.create_task(auto_delete(reply_msg, delay=5))
                return
            
            target_id = None
            target_msg = None
            actual_text = text
            
            parts = text.split(maxsplit=1)
            if parts:
                first_part = parts[0]
                if first_part.startswith('@') or first_part.isdigit():
                    try:
                        user = await client.get_entity(first_part)
                        target_id = user.id
                        actual_text = parts[1] if len(parts) > 1 else ""
                        if not actual_text:
                            reply_msg = await event.reply("❌ No message to spam after target!")
                            if is_saved:
                                asyncio.create_task(auto_delete(reply_msg, delay=5))
                            return
                    except:
                        pass
            
            if event.is_reply and not target_id:
                try:
                    target_msg = await event.get_reply_message()
                    if target_msg:
                        target_id = target_msg.sender_id
                except:
                    pass
            
            chat_id = event.chat_id
            msg_to_send = actual_text if actual_text else text
            
            if target_id:
                user_display = await get_user_display(target_id)
                reply_msg = await event.reply(f"📨 Delayspam: {count} msgs, {delay}s delay to {user_display}")
            else:
                reply_msg = await event.reply(f"📨 Delayspam: {count} msgs, {delay}s delay in this chat")
            
            await asyncio.sleep(0.5)
            
            spam_running = True
            sent = 0
            
            for i in range(count):
                if not spam_running:
                    break
                try:
                    if target_msg:
                        await target_msg.reply(msg_to_send)
                    elif target_id:
                        await client.send_message(target_id, msg_to_send)
                    else:
                        await client.send_message(chat_id, msg_to_send)
                    sent += 1
                    await asyncio.sleep(delay)
                except Exception as e:
                    print(f"Delayspam error: {e}")
                    break
            
            spam_running = False
            
            if target_id:
                await event.reply(f"✅ Delayspam done: {sent}/{count} messages sent to {user_display}")
            else:
                await event.reply(f"✅ Delayspam done: {sent}/{count} messages sent in this chat")
                
            if is_saved:
                asyncio.create_task(auto_delete(event.message, delay=5))
                
        except ValueError:
            reply_msg = await event.reply(f"❌ Use: `.delayspam 1.5 10 hello`")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg, delay=5))
        except Exception as e:
            spam_running = False
            reply_msg = await event.reply(f"❌ Error: {e}")
            if is_saved:
                asyncio.create_task(auto_delete(reply_msg, delay=5))

    @client.on(events.NewMessage(pattern=r"\.offspam$"))
    async def offspam_command(event):
        global spam_running
        if not is_allowed(event.sender_id):
            return
        is_saved = event.is_private and event.chat_id == OWNER_ID
        
        if spam_running:
            spam_running = False
            reply_msg = await event.reply("🛑 Spam stopped!")
        else:
            reply_msg = await event.reply("ℹ️ No spam is currently running.")
        
        if is_saved:
            asyncio.create_task(auto_delete(reply_msg, delay=5))
            asyncio.create_task(auto_delete(event.message, delay=5))
    
    # ========== START ==========
    try:
        await client.start(phone=PHONE_NUMBER)
        me = await client.get_me()
        saved_messages_id = me.id
        print("\n" + "=" * 60)
        print(f"✅ Logged in as: {me.first_name} (@{me.username})")
        print(f"📥 Saved Messages ID: {saved_messages_id}")
        print(f"👑 Owner ID: {OWNER_ID}")
        print(f"👑 Sudo users: {len(sudo_users)}")
        print(f"📊 Mental users: {len(active_users)} | {len(active_users2)} | {len(active_users3)} | {len(active_users4)} | {len(active_users5)} | {len(active_users6)} | {len(active_users7)}")
        print(f"🎨 Font users: {len(active_font1_users)} | {len(active_font2_users)} | {len(active_font3_users)} | {len(active_font4_users)} | {len(active_font5_users)} | {len(active_font6_users)} | {len(active_font7_users)}")
        print(f"🤖 CHUD: {len(active_autoreply)} users")
        print(f"📝 Prefix: {len(global_prefix_list)} set")
        print(f"👤 Username: {len(global_username_list)} set")
        print(f"🏷️ Tag: {len(global_tag_list)} set")
        print(f"📝 Suffix: {len(global_suffix_list)} set")
        print(f"🚫 Block: {len(global_block_list)} words")
        print(f"⚡ Fast Mode: {'ON' if fast_mode else 'OFF'}")
        print(f"🌍 Global Mode: {'ON' if global_mode else 'OFF'}")
        print(f"🧬 Clone Mode: {'ON' if clone_mode else 'OFF'}")
        print(f"📊 Repeat Count: {repeat_count}")
        print(f"📝 OneWord: {len(user_oneword_default)} users, Global: {len(GLOBAL_ONEWORD_LIST)} words")
        print("=" * 60)
        print("🤖 BOT IS READY 101% WORKING!")
        print("📝 Use .help in Saved Messages for commands")
        print("=" * 60)
        await client.run_until_disconnected()
    except Exception as e:
        print(f"❌ FATAL ERROR: {e}")
        import traceback
        traceback.print_exc()
    finally:
        await client.disconnect()
        print("👋 Stopped")

