    if not HOSTED_USERS:
        member_text = "⚠️ *Abhi tak kisi bhi user ne bot se bot host nahi kiya hai!*"
    else:
        member_lines = []
        for i, uid in enumerate(HOSTED_USERS, 1):
            sender = HOSTED_USER_ENTITIES.get(uid)
